mapper.select:
select e.id, e.code, e.name, e.equipment_type_id, et.name as equipment_type_name, e.area_id, a.name as area_name, e.status, e.last_inspection_at from equipment e inner join equipment_type et on et.id = e.equipment_type_id inner join area a on a.id = e.area_id
and ( e.code like concat('%', #{keyword}, '%') or e.name like concat('%', #{keyword}, '%') or e.serial_number like concat('%', #{keyword}, '%') )
and e.equipment_type_id = #{equipmentTypeId}
and e.area_id = #{areaId}
and e.status = #{status}
order by e.created_at desc, e.id desc

select id, code, name, equipment_type_id, area_id
from equipment
where status = 'NORMAL'

    and equipment_type_id = #{equipmentTypeId}


    and area_id = #{areaId}


    and (
        code like concat('%', #{keyword}, '%')
        or name like concat('%', #{keyword}, '%')
    )

order by name, id

mapper.update:
update equipment
set status = #{status}
where id = #{equipmentId}
  and status in ('NORMAL', 'DISABLED')

mapper.select:
select id, status, equipment_type_id from equipment where id in
#{id}
order by id for update
